import { error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { memberApi, MemberApiError } from '$lib/server/member-api';
import { authSettings } from '$lib/server/member-auth';

// The export is generated by the CMS for this session's member only and streamed straight back.
// It is never emailed, stored, cached or logged here.
export const POST: RequestHandler = async ({ locals, request }) => {
  // A body-less POST is not covered by SvelteKit's form origin check, so check it explicitly. The session
  // cookie is also SameSite=Lax, which keeps it off cross-site POSTs.
  let origin: string;
  try { origin = authSettings().origin; } catch { error(503, 'The export is temporarily unavailable.'); }
  if (request.headers.get('origin') !== origin) error(403, 'This export request could not be verified.');
  if (!locals.member || !locals.memberAccessToken) error(401, 'Sign in to export your data.');
  try {
    const data = await memberApi<unknown>(locals, '/api/lifecycle/export', {}, 8 * 1024 * 1024);
    return new Response(JSON.stringify(data, null, 2), { headers: {
      'Content-Type': 'application/json; charset=utf-8', 'Content-Disposition': 'attachment; filename="terrace-member-export.json"',
      'Cache-Control': 'private, no-store', 'X-Robots-Tag': 'noindex, nofollow', 'X-Content-Type-Options': 'nosniff',
    } });
  } catch (failure) {
    if (failure instanceof MemberApiError && [401, 403].includes(failure.status)) error(failure.status, 'This export is not available.');
    error(503, 'The export is temporarily unavailable.');
  }
};
